@Component("order-handler")
@ProcessingGroup("order-processing-group")
public class OrderEventHandler {
	
	// core constructor
	OrderEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateOrderEvent
     */
    @EventHandler
    public void handle( CreateOrderEvent event) {
        entityManager.persist(new Order(event.getOrderId(), event.getOrderNumber(), event.getPlacedDate(), event.getSubtotal(), event.getDiscountTotal(), event.getShippingTotal(), event.getTaxTotal(), event.getGrandTotal(), event.getShippingAddress(), event.getBillingAddress(), event.getCustomer(), event.getChannel(), event.getOrderLines(), event.getPayments(), event.getShipments(), event.getRefunds(), event.getAppliedPromotions(), event.getSeller(), event.getGiftCardRedemptions(), event.getCouponRedemptions(), event.getReturnRequests(), event.getInvoice(), event.getStatus()));
    }

    /*
     * @param	event UpdateOrderEvent
     */
    @EventHandler
    public Order handle( UpdateOrderEvent event) {
    	entityManager.merge(new Order(event.getOrderId(), event.getOrderNumber(), event.getPlacedDate(), event.getSubtotal(), event.getDiscountTotal(), event.getShippingTotal(), event.getTaxTotal(), event.getGrandTotal(), event.getShippingAddress(), event.getBillingAddress(), event.getCustomer(), event.getChannel(), event.getOrderLines(), event.getPayments(), event.getShipments(), event.getRefunds(), event.getAppliedPromotions(), event.getSeller(), event.getGiftCardRedemptions(), event.getCouponRedemptions(), event.getReturnRequests(), event.getInvoice(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteOrderEvent
     */
    @EventHandler
    public void on( DeleteOrderEvent event) {
    	Order entity = new Order();
   
    	// ------------------------------------------
    	// apply the OrderId
    	// ------------------------------------------
    	entity.setOrderId( event.getOrderId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final OrderRepository orderEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(OrderEventHandler.class.getName());

}
